import hashlib

def blob_sha(text):
    b = text.encode('utf-8')
    return hashlib.sha1(b'blob ' + str(len(b)).encode() + b'\x00' + b).hexdigest()

contents = {'a.txt': 'x\n', 'b.txt': 'x\n', 'c.txt': 'y\n', 'd.txt': 'z\n'}
files = list(contents.keys())
unique = {blob_sha(contents[f]) for f in files}
print('文件数:', len(files), '唯一 blob 数:', len(unique))
print('去重率:', round(1 - len(unique) / len(files), 2))
assert len(unique) == 3
